/* 
 * Style Name: Dream Singles - Kuromi Pink & Purple Theme
 * Author: YourUsername
 * Description: Нежный стиль в розово-фиолетовых тонах с падающими сердечками и изображением Ку́роми на фоне. Все элементы сайта становятся полупрозрачными с размытием, кнопки и ссылки окрашиваются в любимые цвета Ку́роми.
 * Homepage URL: https://www.dream-singles.com
 */

@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("dream-singles.com") {
/* ========== 1. ФОН ========== */
    /* Замени ссылку на свою картинку с Ку́роми */
    html, body {
        background-image: url(https://i.postimg.cc/Hn9G8YpJ/kurumi.png) !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-color: #2d0a3d !important;
    }

    /* ========== 2. ПРОЗРАЧНОСТЬ ДЛЯ КОНТЕНТА ========== */
    body main,
    body .content-wrapper,
    body .page-content,
    body .main-content,
    body .container,
    body .panel,
    body .box,
    body .profile-item,
    body .profile-card,
    body .user-item,
    body [class*="profile"],
    body [class*="message"],
    body [class*="chat"] {
        background-color: rgba(255, 240, 250, 0.7) !important;
        backdrop-filter: blur(4px) !important;
        border-radius: 15px !important;
        border: 1px solid #ba55d3 !important;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2) !important;
    }

    /* ========== 3. БОКОВОЕ МЕНЮ ========== */
    .sidebar, .left-menu, nav, [class*="sidebar"], [class*="menu"] {
        background-color: rgba(200, 170, 220, 0.8) !important;
        backdrop-filter: blur(4px) !important;
        border-right: 2px solid #ba55d3 !important;
        border-radius: 0 20px 20px 0 !important;
    }

    .sidebar a, .left-menu a, nav a {
        color: #4a0e6e !important;
        font-weight: 500 !important;
        border-radius: 10px !important;
        transition: all 0.2s !important;
        padding: 5px 10px !important;
        display: block !important;
    }

    .sidebar a:hover, .left-menu a:hover, nav a:hover {
        background-color: rgba(255, 105, 180, 0.3) !important;
        color: #ff1493 !important;
        padding-left: 15px !important;
    }

    /* ========== 4. КАРТОЧКИ ПРОФИЛЕЙ ========== */
    .profile-item, .profile-card, .user-item, [class*="profile"]:not(.sidebar) {
        background-color: rgba(255, 240, 250, 0.8) !important;
        border: 2px solid #ba55d3 !important;
        border-radius: 20px !important;
        margin: 10px !important;
        padding: 10px 15px !important;
        box-shadow: 0 2px 8px rgba(186, 85, 211, 0.3) !important;
    }

    .profile-item .name, .username, .nickname {
        color: #8b008b !important;
        font-weight: bold !important;
        font-size: 1.1em !important;
    }

    .profile-item .city, .location {
        color: #c71585 !important;
        font-style: italic !important;
    }

    .profile-item .about, .description {
        color: #4a0e4a !important;
        line-height: 1.4 !important;
    }

    /* ========== 5. ПАГИНАЦИЯ ========== */
    .pagination, .pages, .pager, [class*="pagination"] {
        background: rgba(255, 240, 250, 0.5) !important;
        border-radius: 30px !important;
        padding: 5px 10px !important;
        border: 1px solid #ba55d3 !important;
        display: inline-block !important;
    }

    .pagination a, .pages a {
        color: #8b008b !important;
        font-weight: bold !important;
        padding: 3px 10px !important;
        border-radius: 50% !important;
        text-decoration: none !important;
    }

    .pagination a:hover, .pages a:hover {
        background-color: #ff69b4 !important;
        color: white !important;
    }

    .pagination .active, .pages .current {
        background-color: #ba55d3 !important;
        color: white !important;
    }

    /* ========== 6. КНОПКИ ========== */
    button, .button, .btn, [type="submit"], [class*="btn"] {
        background: linear-gradient(45deg, #ba55d3, #ff69b4) !important;
        color: white !important;
        border: none !important;
        border-radius: 30px !important;
        padding: 8px 20px !important;
        font-weight: bold !important;
        cursor: pointer !important;
        transition: all 0.2s !important;
        box-shadow: 0 2px 5px rgba(0,0,0,0.2) !important;
        text-shadow: 0 1px 2px rgba(0,0,0,0.2) !important;
    }

    button:hover, .button:hover, .btn:hover {
        transform: scale(1.02) !important;
        background: linear-gradient(45deg, #ff69b4, #ba55d3) !important;
        box-shadow: 0 4px 10px rgba(255, 105, 180, 0.5) !important;
    }

    /* ========== 7. ЗАГОЛОВКИ ========== */
    h1, h2, h3, h4, .title, [class*="title"] {
        color: #8b008b !important;
        text-shadow: 2px 2px 4px rgba(255, 105, 180, 0.3) !important;
    }

    /* ========== 8. ССЫЛКИ ========== */
    a:not(.button):not(.btn) {
        color: #c71585 !important;
        transition: all 0.2s !important;
    }

    a:not(.button):not(.btn):hover {
        color: #ff1493 !important;
        text-decoration: underline wavy #ba55d3 !important;
    }

    /* ========== 9. ПОЛЯ ВВОДА ========== */
    input, textarea, select {
        background-color: rgba(255, 240, 250, 0.9) !important;
        border: 2px solid #dda0dd !important;
        border-radius: 10px !important;
        color: #4a0e4a !important;
        padding: 5px 10px !important;
    }

    input:focus, textarea:focus {
        border-color: #ff69b4 !important;
        box-shadow: 0 0 8px #ff69b4 !important;
        outline: none !important;
    }

    /* ========== 10. ФУТЕР ========== */
    footer, .footer {
        background: rgba(186, 85, 211, 0.5) !important;
        backdrop-filter: blur(3px) !important;
        color: white !important;
        border-top: 2px solid #ffb6c1 !important;
        margin-top: 20px !important;
    }

    footer a, .footer a {
        color: #ffe4f0 !important;
    }

    /* ========== 11. СКРОЛЛБАР ========== */
    ::-webkit-scrollbar {
        width: 10px !important;
        height: 10px !important;
    }

    ::-webkit-scrollbar-track {
        background: #ffe4e1 !important;
        border-radius: 10px !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(45deg, #ba55d3, #ff69b4) !important;
        border-radius: 10px !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #ff69b4 !important;
    }
}
